def county_drive_time_chart(minutes, title, filename):
    mode_df = drive_df[drive_df["minutes"] == minutes].copy()
    county_only = mode_df[mode_df["group"] == "county"]
    pivot = county_only.pivot_table(index="county", columns="time_label", values="percent_covered").reindex(
        columns=TIME_ORDER
    )
    pivot["mean_cov"] = pivot.mean(axis=1)
    pivot = pivot.sort_values("mean_cov").drop(columns="mean_cov")
    state_line = mode_df[mode_df["group"] == "statewide"].set_index("time_label")["percent_covered"].reindex(TIME_ORDER)
    under95_idx = [c for c in pivot.index if c.upper() in {x.upper() for x in under95_counties}]
    rest_idx = [c for c in pivot.index if c.upper() not in {x.upper() for x in under95_counties}]
    line_styles = ["-", "--", ":", "-.", "-", "--", ":", "-.", "-", "--", ":", "-.", "-", "--", ":"]

    fig, ax = plt.subplots(figsize=(13, 7))
    fig.patch.set_facecolor("#1a1a2e")
    for cname in rest_idx:
        ax.plot(x_time, pivot.loc[cname].values, color="#555577", linewidth=0.8, alpha=0.45)
    cmap = plt.cm.get_cmap("tab10", 10)
    for i, cname in enumerate(under95_idx):
        ax.plot(
            x_time,
            pivot.loc[cname].values,
            marker="o",
            linewidth=2,
            markersize=6,
            color=cmap(i % 10),
            linestyle=line_styles[i],
            label=cname.title(),
        )
    ax.plot(
        x_time,
        state_line.values,
        color="white",
        linewidth=2.5,
        linestyle="--",
        marker="D",
        markersize=7,
        label="Statewide avg",
        zorder=5,
    )
    for i, val in enumerate(state_line.values):
        ax.text(i, val + 1.8, f"{val:.1f}%", ha="center", fontsize=8, color="white", fontweight="bold")
    ax.axhline(y=COVERAGE_THRESHOLD, color="#DC3C3C", linewidth=0.8, linestyle="--", alpha=0.6)
    style_ax_time(ax)
    ax.set_xlim(-0.5, len(TIME_ORDER) - 0.5)
    ax.set_title(
        f"{title}\n(counties below {COVERAGE_THRESHOLD:.0f}% highlighted)",
        color="white",
        fontsize=13,
        fontweight="bold",
        pad=15,
    )
    leg = ax.legend(
        facecolor="#2a2a4e",
        labelcolor="white",
        fontsize=8,
        loc="lower left",
        title=f"Under {COVERAGE_THRESHOLD:.0f}% + Statewide",
        title_fontsize=8,
    )
    leg.get_title().set_color("white")
    leg.get_frame().set_edgecolor("#444")
    fig.subplots_adjust(bottom=0.12, top=0.88, left=0.09, right=0.95)
    fig.savefig(f"{OUTPUT_DIR}/{filename}", dpi=150, facecolor=fig.get_facecolor())
    plt.close(fig)
    print(f"Saved: {filename}")


county_drive_time_chart(
    minutes=20,
    title="County Drive Coverage by Time of Day — ≤20 min",
    filename="county_drive_20min_by_time.png",
)

