def county_transit_time_chart(minutes, title, filename):
    mode_df = transit_df[transit_df["minutes"] == minutes].copy()
    county_only = mode_df[mode_df["group"] == "county"]
    pivot = county_only.pivot_table(index="county", columns="time_label", values="percent_covered_restated").reindex(
        columns=TIME_ORDER
    )
    pivot["mean_cov"] = pivot.mean(axis=1)
    pivot = pivot.sort_values("mean_cov").drop(columns="mean_cov")
    state_line = (
        mode_df[mode_df["group"] == "statewide"].set_index("time_label")["percent_covered_restated"].reindex(TIME_ORDER)
    )
    low_idx = [c for c in pivot.index if c.upper() in low_transit]
    rest_idx = [c for c in pivot.index if c.upper() not in low_transit]
    line_styles = ["-", "--", ":", "-.", "-", "--", ":", "-.", "-", "--", ":", "-.", "-", "--", ":"]

    fig, ax = plt.subplots(figsize=(13, 7))
    fig.patch.set_facecolor("#1a1a2e")
    for cname in rest_idx:
        ax.plot(x_time, pivot.loc[cname].values, color="#555577", linewidth=0.8, alpha=0.45)
    cmap = plt.cm.get_cmap("tab10", max(len(low_idx), 1))
    for i, cname in enumerate(low_idx):
        row = pivot.loc[cname]
        ta_pct = county_transit_accessible[county_transit_accessible["county"] == cname][
            "transit_accessible_pct"
        ].values
        ta_str = f" ({ta_pct[0]:.0f}% accessible)" if len(ta_pct) > 0 else ""
        ax.plot(
            x_time,
            row.values,
            marker="o",
            linewidth=2,
            markersize=6,
            color=cmap(i % 10),
            linestyle=line_styles[i],
            label=f"{cname.title()}{ta_str}",
        )
    ax.plot(
        x_time,
        state_line.values,
        color="white",
        linewidth=2.5,
        linestyle="--",
        marker="D",
        markersize=7,
        label="Statewide avg",
        zorder=5,
    )
    for i, val in enumerate(state_line.values):
        ax.text(i, val + 1.8, f"{val:.1f}%", ha="center", fontsize=8, color="white", fontweight="bold")
    style_ax_time(ax)
    ax.set_xlim(-0.5, len(TIME_ORDER) - 0.5)
    ax.set_ylabel("% of Transit-Accessible Voters Covered", color="white", fontsize=11)
    ax.set_title(
        f"{title}\n(% of transit-accessible voters; counties <{LOW_TRANSIT_THRESHOLD:.0f}% accessible flagged)",
        color="white",
        fontsize=13,
        fontweight="bold",
        pad=15,
    )
    leg = ax.legend(
        facecolor="#2a2a4e",
        labelcolor="white",
        fontsize=8,
        loc="lower left",
        title=f"<{LOW_TRANSIT_THRESHOLD:.0f}% accessible + Statewide",
        title_fontsize=8,
    )
    leg.get_title().set_color("white")
    leg.get_frame().set_edgecolor("#444")
    fig.subplots_adjust(bottom=0.12, top=0.88, left=0.09, right=0.95)
    fig.savefig(f"{OUTPUT_DIR}/{filename}", dpi=150, facecolor=fig.get_facecolor())
    plt.close(fig)
    print(f"Saved: {filename}")


