fig.subplots_adjust(bottom=0.18, top=0.88, left=0.1, right=0.92)
fig.savefig(f"{OUTPUT_DIR}/transit_underserved_top15.png", dpi=150, facecolor=fig.get_facecolor())
plt.close(fig)
print("Saved: transit_underserved_top15.png")

